                        if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                            if grid[nr][nc] == color and (nr, nc) not in visited:
                                queue.append((nr, nc))
                shapes.append((color, shape))
    return shapes

def get_metrics(shape):
    min_r = min(r for r, c in shape)
    max_r = max(r for r, c in shape)
    min_c = min(c for r, c in shape)
    max_c = max(c for r, c in shape)
    return {
        'height': max_r - min_r + 1,
        'width': max_c - min_c + 1,
    }

def transform_final(grid):
    orig_shapes = get_shapes(grid)
    # Sort by min_col ascending
    sorted_shapes = sorted(orig_shapes, key=lambda s: min(c for r, c in s[1]))

    # Maximize output dimensions to catch all placements
    height_out = 30
    width_out = 30

    output = [[0] * width_out for _ in range(height_out)]

    for idx, (color, shape) in enumerate(sorted_shapes):
        m = get_metrics(shape)
        h, w = m['height'], m['width']

        # Key formula: row_start = idx + (idx > 0)
        row_start = idx + (1 if idx > 0 else 0)

        for row_rel in range(h):
            num_cols = min(w, h - row_rel)
            for col_rel in range(num_cols):
                out_r = row_start + row_rel
                out_c = idx + col_rel
                if out_r < height_out and out_c < width_out:
                    output[out_r][out_c] = color

    # Crop to 10x10 for submission
    return output[:10][:10]

# Test on all demos
print("=== Running Final Transform ===\n")
for demo_name in ['Demo 1', 'Demo 2', 'Demo 3', 'Test']:
    demo_in = G[f'Demo pair {demo_name.split()[1]} input' if demo_name != 'Test' else 'Test input']
    result = transform_final(demo_in)

    expected_key = f'Demo pair {demo_name.split()[1]} output' if demo_name != 'Test' else None
    if expected_key:
